// Producer
@Autowired KafkaTemplate<String, OrderEvent> kafka;
kafka.send("orders", order.getId(), new OrderEvent(order));   // key = order id -> ordering per order

// Consumer
@KafkaListener(topics = "orders", groupId = "billing")
public void onOrder(OrderEvent event, Acknowledgment ack) {
    if (processedRepo.existsByEventId(event.id())) { ack.acknowledge(); return; } // idempotency
    billingService.charge(event);
    processedRepo.save(new ProcessedEvent(event.id()));
    ack.acknowledge();                       // manual commit after success
}
